-- Generated by the Neutrino Translator from verified MLIR.
-- Idempotent + atomic (a function body runs in a single transaction).
CREATE OR REPLACE FUNCTION attest_core_document_escrow(p_escrow_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_escrow_id AND procedure = 'core_document_escrow' AND reconciled) THEN
        RAISE EXCEPTION 'bad transition';
    END IF;
    INSERT INTO coordination_status(procedure, idempotency_key, attested) VALUES ('core_document_escrow', p_escrow_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET attested = true;
END;
$$;

CREATE OR REPLACE FUNCTION execute_core_document_escrow(p_escrow_id text, p_buyer_id text, p_agent_id text, p_seller_id text, p_amount bigint, p_agreed_amount bigint, p_currency text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    -- (no computed values)
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_escrow_id AND procedure = 'core_document_escrow' AND reconciled) THEN
        RAISE EXCEPTION 'replay';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_escrow_id AND procedure = 'core_document_escrow' AND attested) THEN
        RAISE EXCEPTION 'missing attestation';
    END IF;

    -- idempotency guard (replay-safe): one row per workflow key
    INSERT INTO posting_idempotency(idempotency_key, entry)
    VALUES (p_escrow_id, 'core_document_escrow')
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;  -- already processed; no double posting
    END IF;


    -- debit buyer_escrow (buyer.escrow)
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for buyer_escrow';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('buyer.escrow', p_buyer_id, p_currency, -(p_amount))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(p_amount));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_document_escrow', 'buyer_escrow', 'buyer.escrow', p_buyer_id, p_amount, p_currency, -(p_amount), p_escrow_id);

    -- credit escrow_holding (escrow.holding)
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for escrow_holding';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('escrow.holding', p_agent_id, p_currency, p_amount)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (p_amount);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_document_escrow', 'escrow_holding', 'escrow.holding', p_agent_id, p_amount, p_currency, p_amount, p_escrow_id);

    -- debit escrow_release (escrow.holding) when p_amount >= p_agreed_amount
    IF p_amount >= p_agreed_amount THEN
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for escrow_release';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('escrow.holding', p_agent_id, p_currency, -(p_amount))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(p_amount));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_document_escrow', 'escrow_release', 'escrow.holding', p_agent_id, p_amount, p_currency, -(p_amount), p_escrow_id);
    END IF;

    -- credit seller_settlement (seller.proceeds) when p_amount >= p_agreed_amount
    IF p_amount >= p_agreed_amount THEN
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for seller_settlement';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('seller.proceeds', p_seller_id, p_currency, p_amount)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (p_amount);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('core_document_escrow', 'seller_settlement', 'seller.proceeds', p_seller_id, p_amount, p_currency, p_amount, p_escrow_id);
    END IF;

    -- balanced invariant: this workflow key must net to zero
    IF (SELECT COALESCE(SUM(signed_amount), 0) FROM postings WHERE procedure = 'core_document_escrow' AND idempotency_key = p_escrow_id) <> 0 THEN
        RAISE EXCEPTION 'not balanced for %', p_escrow_id;
    END IF;

    INSERT INTO coordination_status(procedure, idempotency_key, reconciled) VALUES ('core_document_escrow', p_escrow_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET reconciled = true;
END;
$$;
